async function recordWaitlistSignup(request, env) {
  if (request.method !== "POST") return jsonResponse({ error: "Method not allowed." }, 405, { Allow: "POST" });
  const url = new URL(request.url);
  if (request.headers.get("Origin") !== url.origin) return jsonResponse({ error: "リクエストを確認できませんでした。" }, 403);
  if (!request.headers.get("Content-Type")?.toLowerCase().startsWith("application/json")) return jsonResponse({ error: "リクエストを確認できませんでした。" }, 415);
  const contentLength = Number(request.headers.get("Content-Length") || 0);
  if (contentLength > 1500) return jsonResponse({ error: "Invalid signup." }, 413);
  let payload;
  try {
    const reader = request.body?.getReader();
    if (!reader) return jsonResponse({ error: "Invalid response." }, 400);
    const chunks = [];
    let totalBytes = 0;
    while (true) {
      const result = await reader.read();
      if (result.done) break;
      totalBytes += result.value.byteLength;
      if (totalBytes > 1500) { await reader.cancel(); return jsonResponse({ error: "Invalid signup." }, 413); }
      chunks.push(result.value);
    }
    const bytes = new Uint8Array(totalBytes);
    let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    payload = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
  } catch { return jsonResponse({ error: "Invalid response." }, 400); }
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return jsonResponse({ error: "Invalid signup." }, 400);
  if (Object.keys(payload).some((key) => !["campaign_id", "email", "company_website"].includes(key))) return jsonResponse({ error: "Invalid signup." }, 400);
  if (typeof payload.company_website === "string" && payload.company_website.trim()) return jsonResponse({ recorded: true });
  const campaign = getInterestCampaign(env);
  const email = typeof payload.email === "string" ? payload.email.trim().toLowerCase() : "";
  if (!campaign || payload.campaign_id !== campaign.id || email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return jsonResponse({ error: "This test is not open or the email is invalid." }, 400);
  }
  if (isRateLimited(request, "interest")) return jsonResponse({ error: "Please wait before submitting another response." }, 429, { "Retry-After": "600" });
  if (!env.DB) return jsonResponse({ error: "現在、ウェイトリストに登録できません。" }, 503);
  try {
    const result = await env.DB.prepare("INSERT INTO waitlist_signups (campaign_id, email, created_at) VALUES (?, ?, ?) ON CONFLICT(campaign_id, email) DO NOTHING")
      .bind(campaign.id, email, new Date().toISOString()).run();
    return jsonResponse({ recorded: true, already_registered: result.meta?.changes === 0 });
  } catch {
    return jsonResponse({ error: "現在、ウェイトリストに登録できません。" }, 503);
  }
}

async function hashToken(token) {
  const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  return Array.from(new Uint8Array(bytes), b => b.toString(16).padStart(2, '0')).join('');
}
