async function previewCreative(id,env) {
  if (!env.DB || !/^[0-9a-f-]{36}$/.test(id)) return new Response('見つかりませんでした。',{status:404});
  const row = await env.DB.prepare('SELECT ad_image FROM idea_previews WHERE id=?').bind(id).first();
  if (!row?.ad_image) return new Response('画像を表示できません。',{status:404});
  const raw=atob(row.ad_image), bytes=Uint8Array.from(raw, c=>c.charCodeAt(0));
  return new Response(bytes,{headers:{...SECURITY_HEADERS,'Content-Type':'image/webp','Cache-Control':'no-store','X-Robots-Tag':'noindex, nofollow'}});
}
