  if(!row?.owner_hash||await hashToken(token)!==row.owner_hash)return jsonResponse({error:'見つかりませんでした。'},404);
  const results=await env.DB.prepare('SELECT email,created_at FROM preview_signups WHERE preview_id=? ORDER BY created_at DESC LIMIT 1000').bind(id).all();
  const count=await env.DB.prepare('SELECT COUNT(*) AS total FROM preview_signups WHERE preview_id=?').bind(id).first();
