async function localizeError(request, response) {
  if (response.ok || request.headers.get('X-WAT-Language') !== 'en' || !response.headers.get('Content-Type')?.includes('application/json')) return response;
  const data = await response.json();
  if (typeof data.error === 'string') data.error = english(data.error);
  return new Response(JSON.stringify(data), { status: response.status, headers: response.headers });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === '/api/paypal/founder/start') return localizeError(request, await startFounderPayPal(request, env || {}, hashToken));
    const founderPayPal = /^\/paypal\/founder\/([0-9a-f-]{36})\/(return|capture|complete)$/.exec(url.pathname);
    if (founderPayPal) return returnFounderPayPal(request, env || {}, founderPayPal[1], founderPayPal[2]);
    if (url.pathname === '/price-test') return new Response(null, { status: 303, headers: { Location: '/#start' } });
    if (url.pathname === '/price-test' || url.pathname.startsWith('/price-test/')) {
      return priceTestPage(request, env || {});
    }
    if (url.pathname === '/privacy' || url.pathname === '/en/privacy') return privacyPolicy(url.pathname.startsWith('/en/') ? 'en' : 'ja');
    if (url.pathname === '/verify-contact') return verifyContact(request, env || {});
    if (url.pathname === '/api/preview-view') return countPreviewView(request, env || {});
    if (url.pathname.startsWith('/api/public-metrics/')) return publicPreviewMetrics(request, env || {});
    if (url.pathname === '/api/preview-signup') return localizeError(request, await previewSignup(request, env || {}));
    if (url.pathname === '/api/preview-contact') return updatePreviewContact(request, env || {});
    if (url.pathname.startsWith('/api/preview-stats/')) return previewStats(request, env || {});
    if (/^\/preview\/[0-9a-f-]{36}\/creative$/.test(url.pathname)) return previewCreative(url.pathname.split('/')[2], env || {});
    if (/^\/preview\/[0-9a-f-]{36}\/manage$/.test(url.pathname)) return managePreview(url.pathname.split('/')[2], url.searchParams.get('lang') === 'en' ? 'en' : 'ja');
    const paypalRoute = /^\/preview\/([0-9a-f-]{36})\/paypal\/(start|return|capture)$/.exec(url.pathname);
    if (paypalRoute) return campaignPayPal(request, env || {}, paypalRoute[1], paypalRoute[2]);
    if (/^\/preview\/[0-9a-f-]{36}\/price-interest$/.test(url.pathname)) {
      return recordCampaignPriceInterest(request, env?.DB, url.pathname.split('/')[2]);
    }
    if (url.pathname.startsWith('/preview/')) return showPreview(request, env || {});
    if (url.pathname === "/api/preview") return localizeError(request, await generatePreview(request, env || {}));
    if (url.pathname === "/api/checkout") return localizeError(request, await createCheckout(request, env || {}, ctx));
    if (url.pathname === "/api/checkout-status") return verifyCheckout(request, env || {});
    if (url.pathname === "/api/waitlist") return recordWaitlistSignup(request, env || {});
    if (url.pathname === "/interest") {
      const campaign = getInterestCampaign(env || {});
      if (!campaign) return new Response("This interest test is not open.", { status: 404, headers: { ...SECURITY_HEADERS, "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } });
      console.log({ event: "campaign_landing_page_request", campaign_id: campaign.id });
      return new Response(interestPage(campaign), { headers: { ...SECURITY_HEADERS, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    }
    const locale = /^\/en\/?$/.test(url.pathname) ? 'en' : 'ja';
    if (locale !== 'en' && url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", {
        status: 404,
        headers: { ...SECURITY_HEADERS, "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" },
      });
    }
    return new Response(homePage(env || {}, locale), {
      headers: {
        ...SECURITY_HEADERS,
        "Content-Type": "text/html; charset=utf-8",
        "Content-Language": locale,
        "Cache-Control": "no-store",
      },
    });
  },
};
